    let loadFromEmbeddedAssembly (asm: Assembly) =
        let names = asm.GetManifestResourceNames()

        let readResource (name: string) =
            let stream = asm.GetManifestResourceStream(name)

            if isNull stream then
                failwith $"Missing embedded resource '{name}' in {asm.GetName().Name}."

            use stream = stream
            use reader = new StreamReader(stream)
            reader.ReadToEnd()

        let schemas =
            names
            |> Array.filter (fun n ->
                n.EndsWith(".schema.json", StringComparison.OrdinalIgnoreCase)
                && not (n.StartsWith("profiles/", StringComparison.OrdinalIgnoreCase))
                && not (n.Contains("/profiles/", StringComparison.OrdinalIgnoreCase)))
            |> Array.map (fun name ->
                let schema = loadSchemaJson (readResource name)
                schema.TypeName, schema)
            |> Map.ofArray

        let profileSchemasByFile =
            names
            |> Array.filter (fun n ->
                n.EndsWith(".schema.json", StringComparison.OrdinalIgnoreCase)
                && (n.StartsWith("profiles/", StringComparison.OrdinalIgnoreCase)
                    || n.Contains("/profiles/", StringComparison.OrdinalIgnoreCase)))
            |> Array.map (fun name ->
                let fileName =
                    match name.LastIndexOf('/') with
                    | -1 -> name
                    | i -> name.Substring(i + 1)

                fileName, loadSchemaJson (readResource name))
            |> Map.ofArray

        let profilesIndex =
            match
                names
                |> Array.tryFind (fun n ->
                    n.Equals("profiles-index.json", StringComparison.OrdinalIgnoreCase)
                    || n.EndsWith(".profiles-index.json", StringComparison.OrdinalIgnoreCase))
            with
            | None -> Map.empty
            | Some name -> loadProfilesIndexJson (readResource name)

