                    | Some schema -> Some(canonicalProfileUrl url, schema)
                    | None -> None)
                |> Map.ofSeq

        let valueSets =
            match
                names
                |> Array.tryFind (fun n ->
                    n.Equals("valuesets.json", StringComparison.OrdinalIgnoreCase)
                    || n.EndsWith(".valuesets.json", StringComparison.OrdinalIgnoreCase))
            with
            | None -> Map.empty
            | Some name -> loadValueSetsJson (readResource name)

        schemas, valueSets, profiles

    let private normalizeTypeName (t: string) =
        if t.StartsWith("http://hl7.org/fhirpath/System.", StringComparison.Ordinal) then
            match t.Substring("http://hl7.org/fhirpath/System.".Length) with
            | "String" -> "string"
            | "Boolean" -> "boolean"
            | "Integer" -> "integer"
            | "Decimal" -> "decimal"
            | "Date" -> "date"
            | "DateTime" -> "dateTime"
            | "Time" -> "time"
            | other -> other.ToLowerInvariant()
        else
            t

