        | "date"
        | "dateTime"
        | "time"
        | "code"
        | "oid"
        | "id"
        | "markdown"
        | "unsignedInt"
        | "positiveInt"
        | "uuid"
        | "xhtml" -> true
        | _ -> false

    let private dateRegex =
        Regex(@"^([0-9]([0-9]([0-9][1-9]|[1-9]0)|[1-9]00)|[1-9]000)(-(0[1-9]|1[0-2])(-(0[1-9]|[1-2][0-9]|3[0-1]))?)?$", RegexOptions.Compiled)

    let private timeRegex =
        Regex(@"^([01][0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\.[0-9]+)?$", RegexOptions.Compiled)

    let private dateTimeRegex =
        Regex(
