            RegexOptions.Compiled
        )

    let private instantRegex =
        Regex(
            @"^([0-9]([0-9]([0-9][1-9]|[1-9]0)|[1-9]00)|[1-9]000)-(0[1-9]|1[0-2])-(0[1-9]|[1-2][0-9]|3[0-1])T([01][0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\.[0-9]+)?(Z|(\+|-)((0[0-9]|1[0-3]):[0-5][0-9]|14:00))$",
            RegexOptions.Compiled
        )

    let private oidRegex = Regex(@"^urn:oid:[0-2](\.(0|[1-9][0-9]*))+$", RegexOptions.Compiled)

    let private uuidRegex =
        Regex(@"^urn:uuid:[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$", RegexOptions.Compiled)

    let private idRegex = Regex(@"^[A-Za-z0-9\-\.]{1,64}$", RegexOptions.Compiled)

    let private uriRegex = Regex(@"^\S*$", RegexOptions.Compiled)

    let private base64Regex = Regex(@"^(\s*([0-9a-zA-Z\+\/=]){4}\s*)+$", RegexOptions.Compiled)

    let private validateDate path (value: string) =
        if dateRegex.IsMatch value then
            if value.Length >= 7 then
                let monthPart = value.Substring(5, 2)

                match Int32.TryParse monthPart with
                | true, m when m < 1 || m > 12 -> [ fatal "Month should be in range [1; 12]." ]
                | true, _ when value.Length >= 10 ->
                    match DateTime.TryParseExact(value.Substring(0, 10), "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None) with
                    | true, _ -> []
                    | false, _ -> [ fatal $"Invalid date '{value}' at {path}." ]
                | _ -> []
            else
                []
        else if value.Length >= 7 then
            let monthPart = value.Substring(5, 2)

            match Int32.TryParse monthPart with
            | true, m when m < 1 || m > 12 -> [ fatal "Month should be in range [1; 12]." ]
            | _ -> [ fatal $"Invalid date '{value}' at {path}." ]
        else
            [ fatal $"Invalid date '{value}' at {path}." ]

    let private validateBinding
        (valueSets: Map<string, Set<string>>)
        (_path: string)
        (strength: string)
        (valueSet: string)
        (code: string)
        =
        match valueSets |> Map.tryFind (canonicalValueSet valueSet) with
        | None -> []
        | Some allowed when allowed.Count = 0 -> []
        | Some allowed ->
            let c = code.Trim()

            // FHIR codes are case-sensitive.
            if allowed.Contains c then
                []
            else
                let msg = $"The provided code '#{code}' was not found in the value set '{valueSet}'"

                match strength.ToLowerInvariant() with
                | "required" -> [ fatal msg ]
                | "extensible" -> [ warning msg ]
                | "preferred"
                | "example" -> [ information msg ]
                | _ -> []

    let private kindOk (typeName: string) (node: JsonNode) =
        let kind = node.GetValueKind()
        let t = normalizeTypeName typeName

        match t with
        | "boolean" -> kind = JsonValueKind.True || kind = JsonValueKind.False
        | "integer"
        | "positiveInt"
        | "unsignedInt"
        | "decimal" -> kind = JsonValueKind.Number
        // FHIR JSON: integer64 is a string
        | "integer64" -> kind = JsonValueKind.String
        | _ -> kind = JsonValueKind.String

    let private asString (node: JsonNode) =
        if node.GetValueKind() = JsonValueKind.String then
            node.GetValue<string>()
        else
            null

    let private checkPrimitiveFormat (path: string) (typeName: string) (node: JsonNode) =
        let t = normalizeTypeName typeName
        let s = asString node

        match t with
        | "date" when not (isNull s) -> validateDate path s
        | "dateTime" when not (isNull s) ->
            if dateTimeRegex.IsMatch s then []
            else [ fatal $"Invalid dateTime '{s}' at {path}." ]
        | "instant" when not (isNull s) ->
            if instantRegex.IsMatch s then []
            else [ fatal $"Invalid instant '{s}' at {path}." ]
        | "time" when not (isNull s) ->
            if timeRegex.IsMatch s then []
            else [ fatal $"Invalid time '{s}' at {path}." ]
        | "uri"
        | "url"
        | "canonical" when not (isNull s) ->
            if uriRegex.IsMatch s then []
            else [ fatal $"Invalid {t} '{s}' at {path}." ]
        | "oid" when not (isNull s) ->
            if oidRegex.IsMatch s then []
            else [ fatal $"Invalid oid '{s}' at {path}." ]
        | "uuid" when not (isNull s) ->
            if uuidRegex.IsMatch s then []
            else [ fatal $"Invalid uuid '{s}' at {path}." ]
        | "id" when not (isNull s) ->
            if idRegex.IsMatch s then []
            else [ fatal $"Invalid id '{s}' at {path}." ]
        | "base64Binary" when not (isNull s) ->
            if String.IsNullOrWhiteSpace s || base64Regex.IsMatch s then []
            else [ fatal $"Invalid base64Binary at {path}." ]
        | "positiveInt" when node.GetValueKind() = JsonValueKind.Number ->
            let n = node.GetValue<decimal>()
            if n >= 1m && Decimal.Truncate n = n then []
            else [ fatal $"{path}: positiveInt must be an integer >= 1." ]
        | "unsignedInt" when node.GetValueKind() = JsonValueKind.Number ->
            let n = node.GetValue<decimal>()
            if n >= 0m && Decimal.Truncate n = n then []
            else [ fatal $"{path}: unsignedInt must be an integer >= 0." ]
        | "integer" when node.GetValueKind() = JsonValueKind.Number ->
            let n = node.GetValue<decimal>()
            if Decimal.Truncate n = n then []
            else [ fatal $"{path}: integer must not have a fractional part." ]
        | "integer64" when not (isNull s) ->
            match Int64.TryParse(s, NumberStyles.Integer, CultureInfo.InvariantCulture) with
            | true, _ -> []
            | false, _ -> [ fatal $"Invalid integer64 '{s}' at {path}." ]
        | _ -> []

    let private checkPrimitive
        (valueSets: Map<string, Set<string>>)
        (path: string)
        (typeName: string)
        (binding: ElementBinding option)
        (node: JsonNode)
        =
        if isNull node then
            [ fatal $"{path}: null is not allowed." ]
        elif not (kindOk typeName node) then
            [ fatal $"{path}: expected FHIR type '{normalizeTypeName typeName}'." ]
        else
            let s = asString node

            [
                yield! checkPrimitiveFormat path typeName node

                match binding with
                | Some b when not (isNull s) ->
                    yield! validateBinding valueSets path b.Strength b.ValueSet s
                | _ -> ()
            ]

    let private emptyElements =
        Dictionary<string, ElementSchema>(StringComparer.Ordinal) :> IReadOnlyDictionary<string, ElementSchema>

    let private contentReferencePath (cref: string) =
        match cref.IndexOf('#') with
        | -1 -> cref.Trim()
        | i -> cref.Substring(i + 1).Trim()

    let private indexElementsByPath (root: ResourceSchema) =
        let dict = Dictionary<string, ElementSchema>(StringComparer.Ordinal)

        let rec walk (el: ElementSchema) =
            if not (String.IsNullOrEmpty el.Path) then
                dict[el.Path] <- el

            for KeyValue(_, child) in el.Elements do
                walk child

        for KeyValue(_, el) in root.Elements do
            walk el

        dict :> IReadOnlyDictionary<string, ElementSchema>

    let private resolveSchema
        (schemas: Map<string, ResourceSchema>)
        (pathIndex: IReadOnlyDictionary<string, ElementSchema>)
        (schema: ElementSchema)
        : ElementSchema =
        if schema.Elements.Count > 0 then
            schema
        else
            match schema.ContentReference with
            | Some cref ->
                let target = contentReferencePath cref

                match pathIndex.TryGetValue target with
                | true, referenced ->
                    { schema with
                        Types = if schema.Types = [] then referenced.Types else schema.Types
                        Binding = schema.Binding |> Option.orElse referenced.Binding
                        Elements = referenced.Elements }
                | _ -> schema
            | None ->
                schema.Types
                |> List.tryFind (fun t ->
                    let n = normalizeTypeName t
                    not (isPrimitive n) && Map.containsKey n schemas)
                |> Option.map (fun t ->
                    let dt = schemas[normalizeTypeName t]
                    { schema with Elements = dt.Elements })
                |> Option.defaultValue schema

    /// Minimal FHIRPath subset for common StructureDefinition constraints.
    module private FhirPathSubset =

        type private Token =
            | Ident of string
            | NumberLit of decimal
            | Dot
            | LParen
            | RParen
            | And
            | Or
            | Eq
            | Ne
            | Gt
            | Lt
            | Gte
            | Lte
            | Plus
            | Minus
            | Eof

        type private Value =
            | Collection of JsonNode list
            | Boolean of bool
            | Number of decimal
            | Unsupported of string

        let private unsupportedMarkers =
            [| "%"
               "ofType("
               "descendants("
               "trace("
               "select("
               "all("
               "as("
               "is("
               "implies"
               "xor"
               "|" |]

        let private renderTokens (tokens: Token list) =
            tokens
            |> List.choose (fun t ->
                match t with
                | Ident i -> Some i
                | NumberLit n -> Some(string n)
                | Dot -> Some "."
                | LParen -> Some "("
                | RParen -> Some ")"
                | And -> Some " and "
                | Or -> Some " or "
                | Eq -> Some "="
                | Ne -> Some "!="
                | Gt -> Some ">"
                | Lt -> Some "<"
                | Gte -> Some ">="
                | Lte -> Some "<="
                | Plus -> Some "+"
                | Minus -> Some "-"
                | Eof -> None)
            |> String.concat ""

        let private isUnsupportedExpression (expr: string) =
            unsupportedMarkers
            |> Array.exists (fun m -> expr.IndexOf(m, StringComparison.OrdinalIgnoreCase) >= 0)

        let private tokenize (expr: string) : Token list option =
            let chars = expr.ToCharArray()
            let mutable i = 0
            let tokens = ResizeArray<Token>()

            let peek () =
                if i < chars.Length then Some chars.[i] else None

            let advance () =
                i <- i + 1

            let readIdent () =
                let start = i

                while i < chars.Length && (Char.IsLetterOrDigit chars.[i] || chars.[i] = '_') do
                    advance ()

                let raw = expr.Substring(start, i - start)

                match raw.ToLowerInvariant() with
                | "and" -> And
                | "or" -> Or
                | _ -> Ident raw

            let readBacktickIdent () =
                advance () // opening `
                let start = i

                while i < chars.Length && chars.[i] <> '`' do
                    advance ()

                let name = expr.Substring(start, i - start)

                if i < chars.Length && chars.[i] = '`' then
                    advance ()
                    Ident name
                else
                    Ident name

            let mutable ok = true

            let readNumber () =
                let start = i

                while i < chars.Length && Char.IsDigit chars.[i] do
                    advance ()

                if i < chars.Length && chars.[i] = '.' then
                    advance ()

                    while i < chars.Length && Char.IsDigit chars.[i] do
                        advance ()

                let raw = expr.Substring(start, i - start)

                match Decimal.TryParse(raw, NumberStyles.Number, CultureInfo.InvariantCulture) with
                | true, n -> NumberLit n
                | false, _ ->
                    ok <- false
                    NumberLit 0m

            while ok && i < chars.Length do
                match peek () with
                | None -> ()
                | Some c when Char.IsWhiteSpace c -> advance ()
                | Some '.' ->
                    tokens.Add Dot
                    advance ()
                | Some '(' ->
                    tokens.Add LParen
                    advance ()
                | Some ')' ->
                    tokens.Add RParen
                    advance ()
                | Some '+' ->
                    tokens.Add Plus
                    advance ()
                | Some '-' ->
                    tokens.Add Minus
                    advance ()
                | Some '=' ->
                    tokens.Add Eq
                    advance ()
                | Some '!' when i + 1 < chars.Length && chars.[i + 1] = '=' ->
                    tokens.Add Ne
                    advance ()
                    advance ()
                | Some '>' when i + 1 < chars.Length && chars.[i + 1] = '=' ->
                    tokens.Add Gte
                    advance ()
                    advance ()
                | Some '<' when i + 1 < chars.Length && chars.[i + 1] = '=' ->
                    tokens.Add Lte
                    advance ()
                    advance ()
                | Some '>' ->
                    tokens.Add Gt
                    advance ()
                | Some '<' ->
                    tokens.Add Lt
                    advance ()
                | Some '`' -> tokens.Add(readBacktickIdent ())
                | Some c when Char.IsDigit c -> tokens.Add(readNumber ())
                | Some c when Char.IsLetter c || c = '_' -> tokens.Add(readIdent ())
                | Some _ -> ok <- false

            if ok then
                tokens.Add Eof
                Some(List.ofSeq tokens)
            else
                None

        let private asCollection =
            function
            | Collection ns -> ns
            | Boolean b -> [ JsonValue.Create(b) :> JsonNode ]
            | Number n -> [ JsonValue.Create(n) :> JsonNode ]
            | Unsupported _ -> []

        let private isTruthy =
            function
            | Boolean b -> b
            | Collection ns -> ns <> []
            | Number n -> n <> 0m
            | Unsupported _ -> false

        let private flattenNode (node: JsonNode) =
            if isNull node || node.GetValueKind() = JsonValueKind.Null then
                []
            else
                match node with
                | :? JsonArray as arr ->
                    [
                        for i = 0 to arr.Count - 1 do
                            let item = arr[i]

                            if not (isNull item) && item.GetValueKind() <> JsonValueKind.Null then
                                yield item
                    ]
                | _ -> [ node ]

        let private navigate (nodes: JsonNode list) (name: string) =
            nodes
            |> List.collect flattenNode
            |> List.collect (fun n ->
                match n with
                | :? JsonObject as obj ->
                    match tryProp obj name with
                    | Some child -> flattenNode child
                    | None -> []
                | _ -> [])

        let private childrenOf (nodes: JsonNode list) =
            nodes
            |> List.collect flattenNode
            |> List.collect (fun n ->
                match n with
                | :? JsonObject as obj ->
                    [
                        for KeyValue(_, child) in obj do
                            if not (isNull child) && child.GetValueKind() <> JsonValueKind.Null then
                                yield! flattenNode child
                    ]
                | :? JsonArray as arr ->
                    [
                        for i = 0 to arr.Count - 1 do
                            let item = arr[i]

                            if not (isNull item) && item.GetValueKind() <> JsonValueKind.Null then
                                yield item
                    ]
                | _ -> [])

        let private hasValueOf (nodes: JsonNode list) =
            nodes
            |> List.exists (fun n ->
                match n with
                | :? JsonValue -> true
                | _ -> false)

        let private applyFunction (name: string) (args: Value list) (target: Value) : Value =
            match name.ToLowerInvariant(), args with
            | "exists", [] -> Boolean(asCollection target <> [])
            | "empty", [] -> Boolean(asCollection target = [])
            | "count", [] -> Number(decimal (asCollection target).Length)
            | "children", [] -> Collection(childrenOf (asCollection target))
            | "hasvalue", [] -> Boolean(hasValueOf (asCollection target))
            | _ -> Unsupported $"function '{name}'"

        let private primitiveEquals (a: JsonNode) (b: JsonNode) =
            if isNull a || isNull b then
                false
            elif a.GetValueKind() <> b.GetValueKind() then
                false
            else
                match a.GetValueKind() with
                | JsonValueKind.String -> a.GetValue<string>() = b.GetValue<string>()
                | JsonValueKind.Number -> a.GetValue<decimal>() = b.GetValue<decimal>()
                | JsonValueKind.True
                | JsonValueKind.False -> a.GetValue<bool>() = b.GetValue<bool>()
                | _ -> false

        let private compare (op: Token) (left: Value) (right: Value) : Value =
            match left, right with
            | Unsupported u, _
            | _, Unsupported u -> Unsupported u
            | Boolean a, Boolean b ->
                match op with
                | Eq -> Boolean(a = b)
                | Ne -> Boolean(a <> b)
                | _ -> Unsupported "boolean comparison"
            | Number a, Number b ->
                match op with
                | Eq -> Boolean(a = b)
                | Ne -> Boolean(a <> b)
                | Gt -> Boolean(a > b)
                | Lt -> Boolean(a < b)
                | Gte -> Boolean(a >= b)
                | Lte -> Boolean(a <= b)
                | _ -> Unsupported "number comparison"
            | Collection leftNodes, Collection rightNodes when op = Eq || op = Ne ->
                match leftNodes, rightNodes with
                | [ (:? JsonValue as a) ], [ (:? JsonValue as b) ] ->
                    let eq = primitiveEquals a b
                    Boolean(if op = Eq then eq else not eq)
                | _ -> Unsupported "multi-item collection equality"
            | _ -> Unsupported "comparison operands"

        let rec evaluate (expr: string) (context: JsonNode) : Result<bool, string> =
            if String.IsNullOrWhiteSpace expr then
                Error "empty expression"
            elif isUnsupportedExpression expr then
                Error "unsupported FHIRPath features"
            else
                match tokenize expr with
                | None -> Error "tokenize failed"
                | Some tokens ->
                    let mutable pos = 0

                    let peekTok () =
                        if pos < tokens.Length then tokens.[pos] else Eof

                    let nextTok () =
                        let t = peekTok ()
                        if t <> Eof then pos <- pos + 1
                        t

                    // Must not be in the `and` chain: nested `let rec loop` inside parsePostfix
                    // breaks F# offside rules when followed by another `and`.
                    let parseArgList () =
                        match peekTok () with
                        | RParen -> []
                        | _ ->
                            // Zero-arg helpers; `where` is handled in parsePostfix.
                            [ Unsupported "function arguments" ]

                    let rec parseOr () =
                        let mutable left = parseAnd ()

                        while (match peekTok () with
                               | Or -> true
                               | _ -> false) do
                            nextTok () |> ignore
                            let right = parseAnd ()

                            left <-
                                match left, right with
                                | Unsupported u, _
                                | _, Unsupported u -> Unsupported u
                                | l, r -> Boolean(isTruthy l || isTruthy r)

                        left

                    and parseAnd () =
                        let mutable left = parseComparison ()

                        while (match peekTok () with
                               | And -> true
                               | _ -> false) do
                            nextTok () |> ignore
                            let right = parseComparison ()

                            left <-
                                match left, right with
                                | Unsupported u, _
                                | _, Unsupported u -> Unsupported u
                                | l, r -> Boolean(isTruthy l && isTruthy r)

                        left

                    and parseComparison () =
                        let mutable left = parseAdd ()

                        match peekTok () with
                        | Eq
                        | Ne
                        | Gt
                        | Lt
                        | Gte
                        | Lte as op ->
                            nextTok () |> ignore
                            let right = parseAdd ()
                            left <- compare op left right
                        | _ -> ()

                        left

                    and parseAdd () =
                        let mutable left = parseUnary ()

                        while (match peekTok () with
                               | Plus
                               | Minus -> true
                               | _ -> false) do
                            let op = nextTok ()
                            let right = parseUnary ()

                            left <-
                                match left, right, op with
                                | Number a, Number b, Plus -> Number(a + b)
                                | Number a, Number b, Minus -> Number(a - b)
                                | Unsupported u, _, _
                                | _, Unsupported u, _ -> Unsupported u
                                | _ -> Unsupported "additive operands"

                        left

                    and parseUnary () = parsePostfix (parsePrimary ())

                    and parsePrimary () =
                        match nextTok () with
                        | NumberLit n -> Number n
                        | Ident name ->
                            match peekTok () with
                            | LParen ->
                                // Function on the current context node (e.g. children(), hasValue()).
                                nextTok () |> ignore
                                let args = parseArgList ()

                                match nextTok () with
                                | RParen -> applyFunction name args (Collection(flattenNode context))
                                | _ -> Unsupported "missing ')'"
                            | _ -> Collection(navigate (flattenNode context) name)
                        | LParen ->
                            let inner = parseOr ()

                            match nextTok () with
                            | RParen -> inner
                            | _ -> Unsupported "missing ')'"
                        | _ -> Unsupported "expected expression"

                    and parsePostfix (target: Value) =
                        let mutable current = target

                        let rec loop () =
                            match peekTok () with
                            | Dot ->
                                nextTok () |> ignore

                                match nextTok () with
                                | Ident name when
                                    name.Equals("where", StringComparison.OrdinalIgnoreCase)
                                    && (match peekTok () with
                                        | LParen -> true
                                        | _ -> false)
                                    ->
                                    nextTok () |> ignore
                                    let predStart = pos
                                    let mutable depth = 1

                                    while depth > 0 && pos < tokens.Length do
                                        match tokens.[pos] with
                                        | LParen ->
                                            depth <- depth + 1
                                            pos <- pos + 1
                                        | RParen ->
                                            depth <- depth - 1
                                            pos <- pos + 1
                                        | Eof -> depth <- 0
                                        | _ -> pos <- pos + 1

                                    let predEnd = pos - 1

                                    let predExpr =
                                        if predEnd > predStart then
                                            tokens
                                            |> List.skip predStart
                                            |> List.take (predEnd - predStart)
                                            |> renderTokens
                                        else
                                            ""

                                    let filtered =
                                        asCollection current
                                        |> List.filter (fun item ->
                                            match evaluate predExpr item with
                                            | Ok true -> true
                                            | _ -> false)

                                    current <- Collection filtered
                                    loop ()
                                | Ident name ->
                                    match peekTok () with
                                    | LParen ->
                                        nextTok () |> ignore
                                        let args = parseArgList ()

                                        match nextTok () with
                                        | RParen ->
                                            current <- applyFunction name args current
                                            loop ()
                                        | _ -> current <- Unsupported "missing ')'"
                                    | _ ->
                                        current <- Collection(navigate (asCollection current) name)
                                        loop ()
                                | _ -> current <- Unsupported "expected identifier after '.'"
                            | LParen ->
                                current <- Unsupported "unexpected '('"
                            | _ -> ()

                        loop ()
                        current

                    let result = parseOr ()

                    match peekTok () with
                    | Eof ->
                        match result with
                        | Unsupported msg -> Error msg
                        | v -> Ok(isTruthy v)
                    | _ -> Error "trailing tokens"

    let private constraintIssue (path: string) (c: ElementConstraint) (ok: bool) =
        if ok then
            []
        else
            let detail =
                if String.IsNullOrWhiteSpace c.Human then
                    $"{path}: constraint {c.Key} failed ({c.Expression})."
                else
                    $"{path}: {c.Key}: {c.Human}"

            if c.Severity.Equals("warning", StringComparison.OrdinalIgnoreCase)
               || c.Severity.Equals("information", StringComparison.OrdinalIgnoreCase) then
                [ warning detail ]
            else
                [ fatal detail ]

    let private evaluateConstraints (path: string) (constraints: ElementConstraint list) (node: JsonNode) =
        [
            for c in constraints do
                // ele-1 is enforced structurally; skip duplicate schema-driven evaluation.
                if c.Key.Equals("ele-1", StringComparison.OrdinalIgnoreCase) then
                    ()
                else
                    match FhirPathSubset.evaluate c.Expression node with
                    | Ok true -> ()
                    | Ok false -> yield! constraintIssue path c false
                    | Error reason ->
                        let detail =
                            if String.IsNullOrWhiteSpace c.Human then
                                $"{path}: constraint {c.Key} could not be evaluated ({reason}): {c.Expression}"
                            else
                                $"{path}: constraint {c.Key} could not be evaluated ({reason}): {c.Human}"

                        // Full-language gaps (where/descendants/%/…) stay warnings so writes remain usable.
                        // Failures inside the claimed subset are fatal for error-severity constraints.
                        let incompleteEngine =
                            reason.StartsWith("unsupported FHIRPath", StringComparison.OrdinalIgnoreCase)

                        if incompleteEngine
                           || c.Severity.Equals("warning", StringComparison.OrdinalIgnoreCase)
                           || c.Severity.Equals("information", StringComparison.OrdinalIgnoreCase) then
                            yield warning detail
                        else
                            yield fatal detail
        ]

    let private codingCodes (obj: JsonObject) =
        match tryProp obj "coding" with
        | Some(:? JsonArray as arr) ->
            [
                for i = 0 to arr.Count - 1 do
                    match arr[i] with
                    | :? JsonObject as coding ->
                        match tryProp coding "code" with
                        | Some n when n.GetValueKind() = JsonValueKind.String ->
                            yield n.GetValue<string>()
                        | _ -> ()
                    | _ -> ()
            ]
        | _ -> []

    /// Binding on CodeableConcept: at least one coding.code in the value set (when known).
    let private validateCodeableConceptBinding
        (valueSets: Map<string, Set<string>>)
        (path: string)
        (binding: ElementBinding option)
        (obj: JsonObject)
        =
        match binding with
        | Some b ->
            match valueSets |> Map.tryFind (canonicalValueSet b.ValueSet) with
            | None -> []
            | Some allowed when allowed.Count = 0 -> []
            | Some allowed ->
                let codes = codingCodes obj
                let strength = b.Strength.ToLowerInvariant()

                if codes = [] then
                    match strength with
                    | "required" ->
                        [ fatal $"{path}: required binding '{b.ValueSet}' needs a coding.code from the value set." ]
                    | "extensible" ->
                        [ warning $"{path}: extensible binding '{b.ValueSet}' has no coding.code from the value set." ]
                    | "preferred"
                    | "example" ->
                        [ information $"{path}: {strength} binding '{b.ValueSet}' has no coding.code from the value set." ]
                    | _ -> []
                elif codes |> List.exists allowed.Contains then
                    []
                else
                    let shown = codes |> List.tryHead |> Option.defaultValue ""
                    validateBinding valueSets path b.Strength b.ValueSet shown
        | None -> []

    let private validateCodingBinding
        (valueSets: Map<string, Set<string>>)
        (path: string)
        (binding: ElementBinding option)
        (obj: JsonObject)
        =
        match binding with
        | Some b ->
            match tryProp obj "code" with
            | Some n when n.GetValueKind() = JsonValueKind.String ->
                validateBinding valueSets path b.Strength b.ValueSet (n.GetValue<string>())
            | _ ->
                match valueSets |> Map.tryFind (canonicalValueSet b.ValueSet) with
                | Some s when s.Count > 0 ->
                    match b.Strength.ToLowerInvariant() with
                    | "required" -> [ fatal $"{path}: required binding '{b.ValueSet}' needs a code." ]
                    | "extensible" -> [ warning $"{path}: extensible binding '{b.ValueSet}' needs a code." ]
                    | "preferred"
                    | "example" ->
                        [ information $"{path}: {b.Strength} binding '{b.ValueSet}' needs a code." ]
                    | _ -> []
                | _ -> []
        | None -> []

    /// ele-1: All FHIR elements must have a @value or children (non-empty object).
    let private validateEle1 (path: string) (obj: JsonObject) =
        if obj.Count = 0 then
            [ fatal $"{path}: Element must have some content (ele-1)." ]
        else
            []

    /// meta.profile URI / absolute-canonical shape only (profile schema apply is separate).
    let private validateMetaProfileUris (path: string) (obj: JsonObject) =
        match tryProp obj "profile" with
        | Some(:? JsonArray as arr) ->
            [
                for i = 0 to arr.Count - 1 do
                    let item = arr[i]
                    let itemPath = $"{path}.profile[{i}]"

                    if isNull item || item.GetValueKind() <> JsonValueKind.String then
                        yield fatal $"{itemPath}: expected canonical string."
                    else
                        let s = item.GetValue<string>()

                        if String.IsNullOrWhiteSpace s || not (uriRegex.IsMatch s) then
                            yield fatal $"Invalid canonical '{s}' at {itemPath}."
                        elif not (s.StartsWith("http://", StringComparison.Ordinal)
                                  || s.StartsWith("https://", StringComparison.Ordinal)
                                  || s.StartsWith("urn:", StringComparison.Ordinal)) then
                            yield fatal $"{itemPath}: profile canonical should be an absolute URI."
            ]
        | Some _ -> [ fatal $"{path}.profile: expected array." ]
        | None -> []

    let rec private validateAgainst
        (schemas: Map<string, ResourceSchema>)
        (pathIndex: IReadOnlyDictionary<string, ElementSchema>)
        (valueSets: Map<string, Set<string>>)
        (path: string)
        (schema: ElementSchema)
        (node: JsonNode)
        =
        if isNull node then
            if schema.Min >= 1 then
                [ fatal $"{path}: required element missing." ]
            else
                []
        elif schema.Array then
            match node with
            | :? JsonArray as arr ->
                let countIssues =
                    [
                        if arr.Count < schema.Min then
                            yield fatal $"{path}: expected at least {schema.Min} item(s), found {arr.Count}."

                        match schema.Max with
                        | Some max when arr.Count > max ->
                            yield fatal $"{path}: expected at most {max} item(s), found {arr.Count}."
                        | _ -> ()
                    ]

                let itemSchema = { schema with Array = false }

                let itemIssues =
                    [
                        for i = 0 to arr.Count - 1 do
                            let item = arr[i]
                            let itemPath = $"{path}[{i}]"

                            if isNull item then
                                yield fatal $"{itemPath}: null is not allowed."
                            else
                                yield! validateItem schemas pathIndex valueSets itemPath itemSchema item
                    ]

                countIssues @ itemIssues
            | _ -> [ fatal $"{path}: expected array." ]
        else
            validateItem schemas pathIndex valueSets path schema node

    and private validateChoice
        (schemas: Map<string, ResourceSchema>)
        (pathIndex: IReadOnlyDictionary<string, ElementSchema>)
        (valueSets: Map<string, Set<string>>)
        (path: string)
        (schema: ElementSchema)
        (obj: JsonObject)
        =
        let present =
            schema.Choices
            |> List.choose (fun name -> tryProp obj name |> Option.map (fun n -> name, n))

        [
            if present = [] && schema.Min >= 1 then
                let choiceList = String.Join(", ", schema.Choices)
                yield fatal $"{path}: required choice missing (one of {choiceList})."

            match schema.Max, present with
            | Some 1, _ :: _ :: _ ->
                yield fatal $"{path}: only one choice allowed, found {present.Length}."
            | _ -> ()

            for name, node in present do
                let suffix =
                    if name.StartsWith(path, StringComparison.Ordinal) && name.Length > path.Length then
                        name.Substring(path.Length)
                    else
                        ""

                let typeHint =
                    if suffix = "" then
                        schema.Types |> List.tryHead |> Option.defaultValue ""
                    else
                        let t = string (Char.ToLowerInvariant suffix.[0]) + suffix.Substring(1)

                        if schema.Types |> List.exists (fun x -> x.Equals(t, StringComparison.OrdinalIgnoreCase)) then
                            t
                        else
                            schema.Types |> List.tryHead |> Option.defaultValue ""

                let childPath = $"{path}/{name}"

                if isPrimitive typeHint then
                    yield! checkPrimitive valueSets childPath typeHint schema.Binding node
                else
                    let choiceSchema =
                        { Path = childPath
                          Min = 0
                          Max = Some 1
                          Array = false
                          Types = [ typeHint ]
                          Binding = schema.Binding
                          Choices = []
                          ContentReference = None
                          Elements = emptyElements
                          Constraints = [] }
                        |> resolveSchema schemas pathIndex

                    match node with
                    | :? JsonObject
                    | :? JsonArray ->
                        yield! validateAgainst schemas pathIndex valueSets childPath choiceSchema node
                    | _ -> yield fatal $"{childPath}: expected complex type '{typeHint}'."
        ]

    and private validateItem
        (schemas: Map<string, ResourceSchema>)
        (pathIndex: IReadOnlyDictionary<string, ElementSchema>)
        (valueSets: Map<string, Set<string>>)
        (path: string)
        (schema: ElementSchema)
        (node: JsonNode)
        =
        let prim =
            schema.Types
            |> List.map normalizeTypeName
            |> List.tryFind isPrimitive

        match prim with
        | Some t -> checkPrimitive valueSets path t schema.Binding node
        | None ->
            let resolved = resolveSchema schemas pathIndex schema

            match node with
            | :? JsonObject as obj ->
                let structural =
                    if resolved.Elements.Count > 0 then
                        validateObject schemas pathIndex valueSets path resolved obj
                    else
                        []

                let typeName =
                    resolved.Types
                    |> List.map normalizeTypeName
                    |> List.tryFind (fun t -> not (isPrimitive t))
                    |> Option.defaultValue ""

                let bindingIssues =
                    match typeName with
                    | "CodeableConcept" -> validateCodeableConceptBinding valueSets path schema.Binding obj
                    | "Coding" -> validateCodingBinding valueSets path schema.Binding obj
                    | "Meta" -> validateMetaProfileUris path obj
                    | _ -> []

                let ele1 =
                    if resolved.Elements.Count > 0 || typeName <> "" then
                        validateEle1 path obj
                    else
                        []

                let constraintIssues =
                    evaluateConstraints path (schema.Constraints @ resolved.Constraints) obj

                ele1 @ structural @ bindingIssues @ constraintIssues
            | _ ->
                let typeHint =
                    schema.Types
                    |> List.map normalizeTypeName
                    |> List.tryHead
                    |> Option.defaultValue "object"

                [ fatal $"{path}: expected object for type '{typeHint}'." ]

    and private validateObject
        (schemas: Map<string, ResourceSchema>)
        (pathIndex: IReadOnlyDictionary<string, ElementSchema>)
        (valueSets: Map<string, Set<string>>)
        (path: string)
        (schema: ElementSchema)
        (obj: JsonObject)
        =
        [
            for KeyValue(name, child) in schema.Elements do
                let childPath = if path = "" then name else $"{path}.{name}"

                if child.Choices <> [] then
                    yield! validateChoice schemas pathIndex valueSets name child obj
                else
                    match tryProp obj name with
                    | Some childNode ->
                        yield! validateAgainst schemas pathIndex valueSets childPath child childNode
                    | None when child.Min >= 1 -> yield fatal $"{childPath}: required element missing."
                    | None -> ()
        ]

    and private validateResource
        (schemas: Map<string, ResourceSchema>)
        (valueSets: Map<string, Set<string>>)
        (profiles: Map<string, ResourceSchema>)
        (schema: ResourceSchema)
        (root: JsonObject)
        (applyProfiles: bool)
        =
        let pathIndex = indexElementsByPath schema

        [
            match tryProp root "resourceType" with
            | Some n when n.GetValueKind() = JsonValueKind.String ->
                let rt = n.GetValue<string>()

                if rt <> schema.TypeName then
                    yield fatal $"resourceType '{rt}' does not match schema '{schema.TypeName}'."
            | _ -> yield fatal "resourceType is required."

            for name in schema.Required do
                match schema.Elements.TryGetValue name with
                | true, el when el.Choices <> [] -> () // enforced via validateChoice
                | _ when Option.isNone (tryProp root name) ->
                    yield fatal $"{name}: required element missing."
                | _ -> ()

            let rootSchema =
                { Path = schema.TypeName
                  Min = 0
                  Max = Some 1
                  Array = false
                  Types = []
                  Binding = None
                  Choices = []
                  ContentReference = None
                  Elements = schema.Elements
                  Constraints = [] }

            yield! validateObject schemas pathIndex valueSets "" rootSchema root
            yield! evaluateConstraints schema.TypeName schema.Constraints root

            if applyProfiles then
                yield! applyDeclaredProfiles schemas valueSets profiles root
        ]

    and private applyDeclaredProfiles
        (schemas: Map<string, ResourceSchema>)
        (valueSets: Map<string, Set<string>>)
        (profiles: Map<string, ResourceSchema>)
        (root: JsonObject)
        =
        match tryProp root "meta" with
        | Some(:? JsonObject as meta) ->
            match tryProp meta "profile" with
            | Some(:? JsonArray as arr) ->
                [
                    for i = 0 to arr.Count - 1 do
                        let item = arr[i]
                        let itemPath = $"meta.profile[{i}]"

                        if not (isNull item) && item.GetValueKind() = JsonValueKind.String then
                            let canon = canonicalProfileUrl (item.GetValue<string>())

                            if not (String.IsNullOrWhiteSpace canon) then
                                match Map.tryFind canon profiles with
                                | None ->
                                    yield
                                        warning
                                            $"{itemPath}: profile '{canon}' is not loaded; structural profile checks skipped."
                                | Some profileSchema ->
                                    yield! validateResource schemas valueSets profiles profileSchema root false
                ]
            | _ -> []
        | _ -> []

    let private applyForcedProfiles
        (schemas: Map<string, ResourceSchema>)
        (valueSets: Map<string, Set<string>>)
        (profiles: Map<string, ResourceSchema>)
        (forced: string list)
        (root: JsonObject)
        =
        [
            for url in forced do
                let canon = canonicalProfileUrl url

                if not (String.IsNullOrWhiteSpace canon) then
                    match Map.tryFind canon profiles with
                    | None ->
                        yield
                            warning
                                $"profile '{canon}' is not loaded; structural profile checks skipped."
                    | Some profileSchema ->
                        yield! validateResource schemas valueSets profiles profileSchema root false
        ]

    let validate
        (schemas: Map<string, ResourceSchema>)
        (valueSets: Map<string, Set<string>>)
        (profiles: Map<string, ResourceSchema>)
        (schema: ResourceSchema)
        (root: JsonObject)
        =
        validateResource schemas valueSets profiles schema root true

    let validateJsonWithProfiles
        (schemas: Map<string, ResourceSchema>)
        (valueSets: Map<string, Set<string>>)
        (profiles: Map<string, ResourceSchema>)
        (body: string)
        (forcedProfiles: string list)
        =
        if String.IsNullOrWhiteSpace body then
            [ fatal "Request body is required." ]
        else
            try
                match JsonNode.Parse(body) with
                | :? JsonObject as obj ->
                    match tryProp obj "resourceType" with
                    | Some n when n.GetValueKind() = JsonValueKind.String ->
                        let rt = n.GetValue<string>()

                        match Map.tryFind rt schemas with
                        | Some schema when schema.Kind = "complex-type" ->
                            [ fatal $"'{rt}' is a data type, not a resource." ]
                        | Some schema ->
                            [
                                yield! validate schemas valueSets profiles schema obj
                                yield! applyForcedProfiles schemas valueSets profiles forcedProfiles obj
                            ]
                        | None -> [ fatal $"No schema loaded for resourceType '{rt}'." ]
                    | _ -> [ fatal "resourceType is required." ]
                | _ -> [ fatal "Request body must be a JSON object." ]
            with ex ->
                [ fatal $"Unable to parse JSON: {ex.Message}" ]

    let validateJson
        (schemas: Map<string, ResourceSchema>)
        (valueSets: Map<string, Set<string>>)
        (profiles: Map<string, ResourceSchema>)
        (body: string)
        =
        validateJsonWithProfiles schemas valueSets profiles body []
